 Client A --"Move(3,4)"--+                +-----------------------+
 Client B --"Hit(dmg 10)"-+--> mailbox --> | PlayerActor(id=7)     |
 Timer ----"Tick"---------+   [m1|m2|m3]   |  hp = 100             |
                                           |  pos = (0,0)          |
   one message at a time, in order  ------>|  receive(msg):        |
                                           |    Hit  -> hp -= dmg  |
                                           |    Move -> pos = ...  |
                                           +-----------+-----------+
                                                       | reply / send
                                                       v
                                            other actors (Room, Score)

// minimal Java actor: private state + single-threaded mailbox
class PlayerActor {
    private int hp = 100;                         // never shared
    private final ExecutorService mailbox =
        Executors.newSingleThreadExecutor();      // one msg at a time

    void hit(int dmg)  { mailbox.submit(() -> hp -= dmg); }
    Future<Integer> getHp() { return mailbox.submit(() -> hp); }
}

